const upsertTelegramInstallation = `-- name: UpsertTelegramInstallation :one
INSERT INTO telegram_installation (
    workspace_id, agent_id, bot_token_encrypted, bot_username, bot_user_id,
    chat_id, installer_user_id
) VALUES ($1, $2, $3, $4, $5, $6, $7)
ON CONFLICT (agent_id) DO UPDATE SET
    bot_token_encrypted = EXCLUDED.bot_token_encrypted,
    bot_username        = EXCLUDED.bot_username,
    bot_user_id         = EXCLUDED.bot_user_id,
    chat_id             = COALESCE(EXCLUDED.chat_id, telegram_installation.chat_id),
    installer_user_id   = EXCLUDED.installer_user_id,
    status              = 'active',
    updated_at          = now()
RETURNING id, workspace_id, agent_id, bot_token_encrypted, bot_username, bot_user_id, chat_id, installer_user_id, status, installed_at, updated_at, chat_session_id, access_policy, allowed_telegram_user_ids, allowed_chat_ids
`

type UpsertTelegramInstallationParams struct {
	WorkspaceID       pgtype.UUID `json:"workspace_id"`
	AgentID           pgtype.UUID `json:"agent_id"`
	BotTokenEncrypted []byte      `json:"bot_token_encrypted"`
	BotUsername       string      `json:"bot_username"`
	BotUserID         int64       `json:"bot_user_id"`
	ChatID            pgtype.Text `json:"chat_id"`
	InstallerUserID   pgtype.UUID `json:"installer_user_id"`
}

// Re-installing an agent's bot REPLACES the row. Accumulating rows would leave
// stale tokens that each keep receiving updates for the same agent.
func (q *Queries) UpsertTelegramInstallation(ctx context.Context, arg UpsertTelegramInstallationParams) (TelegramInstallation, error) {
	row := q.db.QueryRow(ctx, upsertTelegramInstallation,
		arg.WorkspaceID,
		arg.AgentID,
		arg.BotTokenEncrypted,
		arg.BotUsername,
		arg.BotUserID,
		arg.ChatID,
		arg.InstallerUserID,
	)
	var i TelegramInstallation
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.AgentID,
		&i.BotTokenEncrypted,
		&i.BotUsername,
		&i.BotUserID,
		&i.ChatID,
		&i.InstallerUserID,
		&i.Status,
		&i.InstalledAt,
		&i.UpdatedAt,
		&i.ChatSessionID,
		&i.AccessPolicy,
		&i.AllowedTelegramUserIds,
		&i.AllowedChatIds,
	)
	return i, err
}
